// Interop Envelope tokens made by the real Laravel encrypter and the laravel-interop package
// (fixtures/envelope-vectors.json, regenerated by bin/generate-vectors.php of that package).
// Every vector names the verdict all implementations have to reach.
const { LaravelEncrypter, Envelope, EnvelopeError } = require('../src/index');
const { ALL_CIPHERS, newEnc, rawKey, keySize } = require('./helpers');

const fx = require('../fixtures/envelope-vectors.json');
const b64 = (s) => Buffer.from(s, 'base64');

const encrypterFor = (cipher, rotated) => {
    const size = keySize(cipher);
    const enc = new LaravelEncrypter(b64(fx.key_b64).subarray(0, size), cipher);
    return rotated ? enc.previousKeys([b64(fx.previous_key_b64).subarray(0, size)]) : enc;
};

/** The verdict name, or the opened envelope. */
const judge = (enc, token, v) => {
    try {
        return { opened: Envelope.open(enc, token, { scope: v.scope, leeway: v.leeway, now: v.now }) };
    } catch (e) {
        return { verdict: Envelope.verdict(e) };
    }
};

const expectVerdict = (v, result) => {
    expect(result.verdict || 'ok').toBe(v.expect);
    if (v.expect !== 'ok') return;
    expect(result.opened).toEqual({
        scope: v.scope,
        data: v.data,
        issuedAt: v.iat,
        notBefore: v.nbf === undefined ? null : v.nbf,
        expiresAt: v.exp === undefined ? null : v.exp
    });
};

describe('vectors from the Laravel package', () => {
    test('there are enough of them', () => {
        expect(fx.vectors.length).toBeGreaterThanOrEqual(150);
    });

    test.each(fx.vectors.map((v) => [`${v.cipher}/${v.name}`, v]))('%s', (_name, v) => {
        const enc = encrypterFor(v.cipher, v.key === 'previous');
        expectVerdict(v, judge(enc, v.token, v));

        if (v.expect_without_previous_key) {
            expect(judge(encrypterFor(v.cipher, false), v.token, v).verdict).toBe(v.expect_without_previous_key);
        }
    });

    // The same documents, encrypted by this package, get the same verdicts: the envelope rules do
    // not depend on who encrypted. (encrypt() takes a Buffer, so documents that are not UTF-8 work.)
    test.each(fx.vectors
        .filter((v) => v.plaintext_b64 !== undefined && v.key === 'current' && v.expect !== 'decrypt_error')
        .map((v) => [`${v.cipher}/${v.name}`, v]))('re-encrypted %s', (_name, v) => {
        const enc = encrypterFor(v.cipher, false);
        expectVerdict(v, judge(enc, enc.encrypt(b64(v.plaintext_b64), false), v));
    });
});

describe('tokens that are not envelopes', () => {
    test('are invalid, not decrypt errors', () => {
        const enc = newEnc('aes-256-cbc');
        for (const token of [enc.encryptString('hello'), enc.encryptCookie('laravel_session', 'abc'), enc.encrypt('hello')]) {
            expect(() => Envelope.open(enc, token, { scope: 's' })).toThrow(EnvelopeError);
            expect(judge(enc, token, { scope: 's' }).verdict).toBe('invalid');
        }
    });

    test('a token that does not decrypt keeps the encrypter\'s error', () => {
        const enc = newEnc('aes-256-cbc');
        let error;
        try {
            Envelope.open(enc, 'not a payload', { scope: 's' });
        } catch (e) {
            error = e;
        }
        expect(error).not.toBeInstanceOf(EnvelopeError);
        expect(error.message).toMatch(/The payload is invalid/);
        expect(Envelope.verdict(error)).toBe('decrypt_error');
    });
});

const NOW = 1700000000;

describe.each(ALL_CIPHERS)('%s', (cipher) => {
    const enc = newEnc(cipher);

    test('round-trips every kind of data', () => {
        for (const data of [null, true, 0, -7, 1.5, '', 'Grüße 世界 🚀 "q" \\ / <t> &', [], {}, [1, 'two', [3], null], { a: { b: null } }]) {
            const token = Envelope.seal(enc, { scope: 'test', data, expiresIn: 60 });
            const opened = Envelope.open(enc, token, { scope: 'test' });
            expect(opened.data).toEqual(data);
            expect(opened.scope).toBe('test');
        }
    });
});

describe('sealing', () => {
    const enc = newEnc('aes-256-cbc');
    const seal = (options) => Envelope.seal(enc, { scope: 's', data: 1, now: NOW, ...options });
    const open = (token, options) => Envelope.open(enc, token, { scope: 's', ...options });

    test('reports the timestamps', () => {
        let opened = open(seal({ expiresIn: 3600, notBefore: NOW + 10 }), { now: NOW + 20 });
        expect([opened.issuedAt, opened.notBefore, opened.expiresAt]).toEqual([NOW, NOW + 10, NOW + 3600]);

        opened = open(seal({ neverExpires: true }), { now: NOW + 20 });
        expect([opened.notBefore, opened.expiresAt]).toEqual([null, null]);

        opened = open(seal({ expiresAt: NOW + 99 }), { now: NOW + 20 });
        expect(opened.expiresAt).toBe(NOW + 99);

        // Dates work too
        opened = open(seal({ expiresAt: new Date((NOW + 77) * 1000), notBefore: new Date(NOW * 1000) }), { now: NOW + 20 });
        expect([opened.notBefore, opened.expiresAt]).toEqual([NOW, NOW + 77]);
    });

    test('checks the scope, not before and expiry against the clock', () => {
        const token = seal({ expiresIn: 100, notBefore: NOW + 50 });
        const verdict = (options) => {
            try {
                open(token, options);
                return 'ok';
            } catch (e) {
                return e.kind;
            }
        };
        expect(verdict({ now: NOW + 49 })).toBe('not_yet_valid');
        expect(verdict({ now: NOW + 50 })).toBe('ok');
        expect(verdict({ now: NOW + 99 })).toBe('ok');
        expect(verdict({ now: NOW + 100 })).toBe('expired');
        expect(verdict({ now: NOW + 60, scope: 'other' })).toBe('scope_mismatch');
        expect(verdict({ now: NOW + 500, scope: 'other' })).toBe('scope_mismatch'); // the scope is judged first
    });

    test('the leeway widens both time checks', () => {
        const token = seal({ expiresIn: 100, notBefore: NOW + 50 });
        const verdict = (now, leeway) => {
            try {
                open(token, { now, leeway });
                return 'ok';
            } catch (e) {
                return e.kind;
            }
        };
        expect(verdict(NOW + 40, 10)).toBe('ok');
        expect(verdict(NOW + 39, 10)).toBe('not_yet_valid');
        expect(verdict(NOW + 109, 10)).toBe('ok');
        expect(verdict(NOW + 110, 10)).toBe('expired');
    });

    test('uses the real clock by default', () => {
        const live = Envelope.seal(enc, { scope: 's', data: 'x', expiresIn: 60 });
        expect(Envelope.open(enc, live, { scope: 's' }).data).toBe('x');
        const dead = Envelope.seal(enc, { scope: 's', data: 'x', expiresAt: 1 });
        expect(() => Envelope.open(enc, dead, { scope: 's' })).toThrow('The envelope has expired.');
    });

    test('rejects arguments that cannot make a good envelope', () => {
        const bad = [
            {},
            { scope: '', data: 1, neverExpires: true },
            { scope: 's', neverExpires: true }, // no data
            { scope: 's', data: 1 }, // no expiry chosen
            { scope: 's', data: 1, expiresIn: 60, neverExpires: true }, // two chosen
            { scope: 's', data: 1, expiresIn: 60, expiresAt: NOW },
            { scope: 's', data: 1, expiresIn: 0 },
            { scope: 's', data: 1, expiresIn: 1.5 },
            { scope: 's', data: 1, expiresIn: '60' },
            { scope: 's', data: 1, expiresAt: 0 },
            { scope: 's', data: 1, expiresAt: -5 },
            { scope: 's', data: 1, expiresAt: 'tomorrow' },
            { scope: 's', data: 1, neverExpires: true, notBefore: 1.5 },
            { scope: 's', data: 1, neverExpires: true, now: 'x' },
            { scope: 5, data: 1, neverExpires: true }
        ];
        for (const options of bad) {
            expect(() => Envelope.seal(enc, options)).toThrow(TypeError);
        }
        expect(() => Envelope.seal(enc)).toThrow(TypeError);
        expect(() => Envelope.seal(enc, { scope: 's', data: 10n, neverExpires: true })).toThrow(TypeError); // BigInt is not JSON
    });

    test('rejects bad open arguments', () => {
        const token = seal({ neverExpires: true });
        expect(() => Envelope.open(enc, token)).toThrow(TypeError);
        expect(() => Envelope.open(enc, token, { scope: 5 })).toThrow(TypeError);
        expect(() => Envelope.open(enc, token, { scope: 's', leeway: -1 })).toThrow(TypeError);
        expect(() => Envelope.open(enc, token, { scope: 's', leeway: 1.5 })).toThrow(TypeError);
    });

    test('previous keys apply', () => {
        const old = newEnc('aes-256-cbc', 0x7a);
        const token = Envelope.seal(old, { scope: 's', data: 'legacy', expiresIn: 60 });
        const rotated = newEnc('aes-256-cbc').previousKeys([rawKey('aes-256-cbc', 0x7a)]);
        expect(Envelope.open(rotated, token, { scope: 's' }).data).toBe('legacy');
        expect(() => Envelope.open(enc, token, { scope: 's' })).toThrow(/Decryption failed/);
    });

    test('an EnvelopeError carries its kind and name', () => {
        const error = new EnvelopeError('expired', 'x');
        expect([error.kind, error.name, error.message, error instanceof Error]).toEqual(['expired', 'EnvelopeError', 'x', true]);
    });
});
